/* Token Radar lane 4A — dark board, teal accent, amber for the watchlist. */
:root {
  --bg: #0a1120; --panel: #101c31; --panel2: #0d1728; --line: #22344f;
  --text: #e7eef8; --muted: #93a5bf; --faint: #64748f;
  --accent: #2dd4bf; --accent-dim: #14b8a6; --amber: #fbbf24; --red: #f87171; --green: #4ade80;
}
* { box-sizing: border-box; }
html { background: var(--bg); }
body { margin: 0; background: var(--bg); color: var(--text);
  font: 14px/1.5 -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }
main { max-width: 1180px; margin: 0 auto; padding: 16px 22px 36px; }
a { color: var(--accent); }
h1 { font-size: 26px; letter-spacing: .04em; margin: 0 0 6px; }
h1 .tag { font-size: 11px; color: var(--bg); background: var(--accent);
  border-radius: 4px; padding: 2px 7px; vertical-align: middle; letter-spacing: .08em; }
.sub { color: var(--muted); margin: 0; max-width: 720px; }
.sub strong { color: var(--text); }
.top { display: flex; justify-content: space-between; gap: 24px; flex-wrap: wrap;
  border-bottom: 1px solid var(--line); padding-bottom: 12px; }
.stats { display: flex; gap: 10px; flex-wrap: wrap; align-content: flex-start; }
.stat { background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  padding: 7px 12px; min-width: 108px; }
.stat b { display: block; font-size: 18px; color: var(--accent); }
.stat span { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }
.method { background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
  padding: 12px 16px; margin: 12px 0; font-size: 13px; color: var(--muted); }
.method h2 { font-size: 13px; color: var(--text); margin: 0 0 6px; text-transform: uppercase; letter-spacing: .07em; }
.method code { color: var(--accent); background: var(--panel2); padding: 1px 5px; border-radius: 4px; font-size: 12px; }
.method .cols { display: flex; gap: 28px; flex-wrap: wrap; margin-top: 8px; }
.method .cols div { min-width: 200px; }
.method b { color: var(--text); }
.controls { display: flex; gap: 14px; flex-wrap: wrap; align-items: end;
  background: var(--panel2); border: 1px solid var(--line); border-radius: 10px; padding: 10px 14px; }
.controls label { font-size: 12px; color: var(--muted); display: flex; flex-direction: column; gap: 4px; }
.controls label.check { flex-direction: row; align-items: center; gap: 6px; padding-bottom: 6px; color: var(--text); }
.controls input[type=search], .controls select { background: var(--panel); color: var(--text);
  border: 1px solid var(--line); border-radius: 6px; padding: 7px 26px 7px 9px; font-size: 13px; min-width: 170px; }
.controls select#sort { min-width: 218px; }
.controls select#cat { min-width: 180px; }
.count { color: var(--muted); font-size: 13px; margin: 10px 2px 6px; }
.count b { color: var(--text); }
table.board { width: 100%; border-collapse: collapse; background: var(--panel);
  border: 1px solid var(--line); border-radius: 10px; overflow: hidden; font-size: 13px; }
.board th, .board td { padding: 6px 10px; text-align: left; border-bottom: 1px solid var(--line); }
.board thead th { background: var(--panel2); color: var(--muted); font-size: 11px;
  text-transform: uppercase; letter-spacing: .06em; }
.board tbody tr { cursor: pointer; }
.board tbody tr:hover, .board tbody tr.sel { background: #16263f; }
.board td.num, .board th.num { text-align: right; font-variant-numeric: tabular-nums; }
.board .name { font-weight: 600; }
.board td:first-child { font-weight: 700; font-size: 15px; }
/* The current top 3 are the scan anchor: their rank numerals carry the accent. */
.board tbody tr:nth-child(-n+3) td:first-child { color: var(--accent); }
.board td.num strong { color: var(--accent); }
.detail .equation { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 13px;
  background: var(--panel2); border: 1px solid var(--line); border-radius: 8px; padding: 9px 12px; margin: 12px 0 0; color: var(--text); }
.method details { margin-top: 8px; }
.method summary { cursor: pointer; color: var(--text); font-size: 12px; }
.board .slug { color: var(--faint); font-size: 11px; font-weight: 400; }
.badge { display: inline-block; font-size: 10px; font-weight: 700; color: #231a04;
  background: var(--amber); border-radius: 4px; padding: 1px 5px; margin-left: 6px; vertical-align: 1px; }
.up { color: var(--green); } .down { color: var(--red); }
.capflag { color: var(--amber); font-size: 11px; }
.barcol { width: 120px; }
.bar { height: 8px; background: var(--panel2); border-radius: 4px; overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.detail { background: var(--panel); border: 1px solid var(--accent-dim); border-radius: 10px;
  padding: 16px 18px; margin: 0 0 16px; scroll-margin-top: 12px; }
.detail h2 { margin: 0 0 4px; font-size: 20px; }
.detail .meta { color: var(--muted); font-size: 13px; margin-bottom: 12px; }
.detail h3 { font-size: 12px; text-transform: uppercase; letter-spacing: .07em; color: var(--muted); margin: 14px 0 6px; }
.breakdown { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px; }
.breakdown div { background: var(--panel2); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; }
.breakdown b { display: block; font-size: 15px; color: var(--accent); }
.breakdown span { font-size: 11px; color: var(--muted); }
.detail ol { margin: 0; padding-left: 20px; }
.detail ol li { margin-bottom: 8px; }
.detail .note { color: var(--muted); font-size: 12px; margin-top: 12px; }
.detail button { background: none; border: 1px solid var(--line); color: var(--muted);
  border-radius: 6px; padding: 4px 10px; cursor: pointer; float: right; }
.live { margin-top: 26px; }
.live h2 { font-size: 15px; margin: 0 0 4px; }
.live p { color: var(--muted); font-size: 13px; margin: 0 0 10px; }
.live table { width: 100%; border-collapse: collapse; background: var(--panel);
  border: 1px solid var(--line); font-size: 13px; }
.live th, .live td { padding: 7px 10px; text-align: left; border-bottom: 1px solid var(--line); }
.live th { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .06em; }
.live td.num, .live th.num { text-align: right; font-variant-numeric: tabular-nums; }
.bycat { margin-top: 26px; }
.calib { margin-top: 26px; }
.audit { margin-top: 26px; }
.bycat h2, .calib h2, .audit h2 { font-size: 15px; margin: 0 0 4px; }
.bycat p, .calib p, .audit p { color: var(--muted); font-size: 13px; margin: 0 0 10px; }
.bycat table, .calib table, .audit table { width: 100%; border-collapse: collapse; background: var(--panel);
  border: 1px solid var(--line); font-size: 13px; }
.bycat th, .bycat td, .calib th, .calib td, .audit th, .audit td { padding: 7px 10px; text-align: left; border-bottom: 1px solid var(--line); }
.bycat th, .calib th, .audit th { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .06em; }
.bycat td.num, .bycat th.num, .calib td.num, .calib th.num, .audit td.num, .audit th.num { text-align: right; font-variant-numeric: tabular-nums; }
.calib tr.median td { background: #2b2305; }
.calib tr.median td.num strong { color: var(--amber); }
.medflag { color: var(--amber); font-size: 11px; font-weight: 700; }
footer { color: var(--faint); font-size: 12px; border-top: 1px solid var(--line); margin-top: 26px; padding-top: 14px; }
.empty { color: var(--muted); padding: 18px; text-align: center; }
